import type { CSSResult, CSSResultGroup } from "lit";

type StyleProperty = { name: string; syntax: string; inherits: boolean; initialValue?: string };
type PropertyRegistry = { registerProperty(property: StyleProperty): void };
const definitions = new WeakMap<CSSResult, readonly StyleProperty[]>();
const registered = new WeakMap<PropertyRegistry, Map<string, string>>();
const signature = (property: StyleProperty) => JSON.stringify([property.syntax, property.inherits, property.initialValue]);

/** Associates generated defaults with a stylesheet without changing a document. */
export function withStyleProperties(style: CSSResult, properties: readonly StyleProperty[]): CSSResult {
  definitions.set(
    style,
    properties.map((property) => ({ ...property })),
  );
  return style;
}

/** Installs the defaults used by these styles in the component's document registry. */
export function registerStyleProperties(styles: CSSResultGroup | undefined, registry: PropertyRegistry | undefined): void {
  if (!registry || typeof registry.registerProperty !== "function") return;
  const known = registered.get(registry) ?? new Map<string, string>();
  const pending = new Map<string, StyleProperty>();
  const collect = (group: CSSResultGroup | undefined): void => {
    if (!group) return;
    if (Array.isArray(group)) {
      for (const style of group) collect(style);
      return;
    }
    for (const property of definitions.get(group as CSSResult) ?? []) {
      const previous = pending.get(property.name);
      const expected = previous ? signature(previous) : known.get(property.name);
      if (expected !== undefined && expected !== signature(property)) throw new Error("Conflicting CSS registration: " + property.name);
      if (!known.has(property.name)) pending.set(property.name, property);
    }
  };
  collect(styles);
  for (const property of pending.values()) {
    try {
      registry.registerProperty(property);
    } catch (error) {
      if (!error || typeof error !== "object" || !("name" in error) || error.name !== "InvalidModificationError") throw error;
    }
    known.set(property.name, signature(property));
    registered.set(registry, known);
  }
}

src/shared/numeric-tokens.ts.source:
export const numericTokenKeys = Object.freeze([0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5, 4, 4.5, 5, 6, 7, 8, 9, 10, 11, 12, 14, 16, 20, 24, 28, 32, 36, 40, 44, 48, 52, 56, 60, 64, 72, 80, 96] as const);
export type NumericTokenKey = (typeof numericTokenKeys)[number];
export type NumericTokenCategory = "spacing" | "sizes";
export type NumericTokenDefinition = Readonly<{
  category: NumericTokenCategory;
  key: NumericTokenKey;
  cssProperty: string;
  defaultValue: `${number}rem`;
}>;

function checkCategory(category: NumericTokenCategory): void {
  if (category !== "spacing" && category !== "sizes") throw new TypeError("Unknown numeric token category: " + category);
}

function checkKey(key: number): asserts key is NumericTokenKey {
  if (typeof key !== "number" || !(numericTokenKeys as readonly number[]).includes(key)) throw new TypeError("Unknown numeric token key: " + key);
}

/** Positive token properties are independent for spacing and dimensions. */
export function numericTokenProperty(category: NumericTokenCategory, key: NumericTokenKey): string {
  checkCategory(category);
  checkKey(key);
  return `--acme-${category === "spacing" ? "spacing" : "size"}-${String(key).replace(".", "-")}`;
}

/** Signed spacing follows its positive theme token; size tokens remain nonnegative. */
export function numericTokenValue(category: NumericTokenCategory, key: number): string {
  checkCategory(category);
  if (typeof key !== "number") throw new TypeError("Numeric token keys must be numbers");
  if (category === "sizes" && key < 0) throw new TypeError("Size tokens cannot be negative");
  const positive = Math.abs(key);
  checkKey(positive);
  const value = `var(${numericTokenProperty(category, positive)})`;
  return key < 0 ? `calc(${value} * -1)` : value;
}

/** Shared generator and manifest input; negative spacing has no separate declaration. */
export const numericTokenDefinitions: readonly NumericTokenDefinition[] = Object.freeze(
  (["spacing", "sizes"] as const).flatMap((category) =>
    numericTokenKeys.map((key) => Object.freeze({ category, key, cssProperty: numericTokenProperty(category, key), defaultValue: `${key * 0.25}rem` as const })),
  ),
);
